<script setup lang="ts">
import { computed,onBeforeUnmount,ref } from 'vue'
import { useRouter } from 'vue-router'
import { accountApi,type ClosureMode,type ClosureTicket } from '@/api/accounts'
import { authStore } from '@/stores/auth'
const router=useRouter(),mode=ref<ClosureMode>('SUSPEND'),password=ref(''),otp=ref(''),text=ref(''),ticket=ref<ClosureTicket>(),remaining=ref(5),busy=ref(false),error=ref('')
const confirmation=computed(()=>mode.value==='PURGE'?'永久注销':'停用账号')
let active=true,timer:ReturnType<typeof setInterval>|undefined;const owner=authStore.state.user?.id
function reset(){if(timer)clearInterval(timer);timer=undefined;ticket.value=undefined;password.value='';otp.value='';text.value=''}
onBeforeUnmount(()=>{active=false;reset()})
async function prepare(){if(busy.value)return;busy.value=true;error.value='';try{const result=await accountApi.prepare(mode.value,password.value);if(!active||owner!==authStore.state.user?.id)return;ticket.value=result;remaining.value=result.waitSeconds;const deadline=performance.now()+result.waitSeconds*1000;timer=setInterval(()=>{remaining.value=Math.max(0,Math.ceil((deadline-performance.now())/1000));if(!remaining.value&&timer){clearInterval(timer);timer=undefined}},100)}catch(e){if(active)error.value=(e as Error).message}finally{busy.value=false}}
async function close(){if(busy.value||remaining.value||!ticket.value||text.value!==confirmation.value)return;busy.value=true;error.value='';try{await accountApi.close(ticket.value.token,text.value,password.value,otp.value);if(!active||owner!==authStore.state.user?.id)return;const suspended=mode.value==='SUSPEND';authStore.clearSession();reset();await router.push({path:'/login',query:suspended?{mode:'reactivate'}:{closed:'1'}})}catch(e){if(active)error.value=(e as Error).message}finally{password.value='';otp.value='';busy.value=false}}
</script>
<template><article class="panel settings-card"><header><div><h3>停用或注销账号</h3><p>普通退出登录请使用账号菜单。以下操作会立即退出所有设备。</p></div></header><p v-if="error" class="form-error" role="alert">{{error}}</p><form class="settings-form" @submit.prevent="ticket?close():prepare()"><fieldset :disabled="!!ticket||busy" class="closure-choices"><legend>选择操作</legend><label><input v-model="mode" type="radio" value="SUSPEND" /><span><strong>暂时停用</strong><small>保留个人数据并暂停登录。之后可在登录页凭密码和双重验证恢复。</small></span></label><label><input v-model="mode" type="radio" value="PURGE" /><span><strong>永久注销</strong><small>删除私密笔记、知识卡、背词记录与 AI 配置，不可恢复。已发送的交流记录和必要交易记录保留，身份显示为已注销用户；共享附件仍供原会话成员访问。训练文件和私有附件由后台清理，备份按原保留期限过期。</small></span></label></fieldset><p>群主须先交接或解散群组；平台仅剩的管理员不能注销。</p><label class="field-label">当前密码<input v-model="password" class="field-input" type="password" autocomplete="current-password" required maxlength="100" :disabled="busy" /></label><template v-if="ticket"><p role="status">{{remaining?`请阅读说明，${remaining} 秒后可确认。`:'等待已完成，请填写确认文字。'}} 此次确认五分钟内有效。</p><label class="field-label">输入“{{confirmation}}”<input v-model="text" class="field-input" maxlength="20" :disabled="busy" autocomplete="off" /></label><label class="field-label">验证码或恢复码（已启用时必填）<input v-model="otp" class="field-input" autocomplete="one-time-code" maxlength="32" :disabled="busy" /></label><div class="closure-actions"><button class="button button--ghost" type="button" :disabled="busy" @click="reset">取消</button><button class="button button--dark" :disabled="busy||remaining>0||text!==confirmation||!password">确认{{confirmation}}</button></div></template><button v-else class="button button--ghost" :disabled="busy||!password">{{busy?'正在核对…':'继续，查看确认步骤'}}</button></form></article></template>
<style scoped>.closure-choices{border:0;padding:0;display:grid;gap:14px}.closure-choices label{display:flex;align-items:flex-start;gap:12px;padding:18px;border:1px solid var(--line);border-radius:6px}.closure-choices input{margin-top:4px}.closure-choices strong,.closure-choices small{display:block}.closure-choices small{margin-top:8px;line-height:1.8;color:var(--muted)}.closure-actions{display:flex;gap:12px;justify-content:flex-end}</style>
